 16	import type { FieldConfig, RawValues } from '../../shared/field-config.model';
 17	import { validateField } from '../../shared/field-validators';
 18	import { hydrate } from '../../shared/field-values';
 19	
 20	/**
 21	 * The step 1 form (ADR-0004): Signal Forms over the shared validation core. The editing model is
 22	 * `Record<string, string | boolean>` (never null); each field has exactly one `validate()` that
 23	 * calls the pure `validateField`. Built once per instance, hydrated from the wizard state; a
 24	 * different configuration means a new instance (the page recreates it).
 25	 */
 26	@Component({
 27	  selector: 'app-quote-form',
 28	  imports: [FormField, FormRoot],
 29	  templateUrl: './quote-form.html',
 30	  styleUrl: './quote-form.css',
 31	})
 32	export class QuoteForm implements OnInit {
 33	  readonly configs = input.required<FieldConfig[]>();
 34	  readonly countryCode = input.required<string>();
 35	
 36	  private readonly appRef = inject(ApplicationRef);
 37	  private readonly injector = inject(Injector);
 38	  private readonly clock = inject(CLOCK);
 39	  private readonly quote = inject(QuoteStore);
 40	  private readonly router = inject(Router);
 41	
 42	  protected form!: FieldTree<RawValues>;
 43	
 44	  ngOnInit(): void {
 45	    const configs = this.configs();
 46	    const model = signal<RawValues>(hydrate(configs, this.quote.values()));
 47	    this.form = form(
 48	      model,
 49	      (root) => {
 50	        for (const config of configs) {
 51	          validate(root[config.key], ({ value }) => {
 52	            const message = validateField(config, value(), this.clock());
 53	            return message ? { kind: 'custom', message } : undefined;
 54	          });
 55	        }
 56	      },
 57	      {
 58	        injector: this.injector,
 59	        submission: {
 60	          action: async () => {
 61	            if (this.quote.completeStep1(configs) !== null) {
 62	              await this.router.navigate(['/', this.countryCode().toLowerCase(), 'planes']);
 63	            }
 64	            return undefined;
 65	          },
 66	          onInvalid: (root) => {
 67	            const first = configs.find((config) => root[config.key]().invalid());
 68	            if (first) root[first.key]().focusBoundControl();
 69	          },
 70	        },
 71	      },
 72	    );
 73	
 74	    // The raw editing values are written to the wizard state on every change (ADR-0003).
 75	    let synced: RawValues = { ...model() };
 76	    effect(
 77	      () => {
 78	        const current = model();
 79	        untracked(() => {
 80	          for (const [key, value] of Object.entries(current)) {
 81	            if (synced[key] !== value) this.quote.setValue(key, value);
 82	          }
 83	          synced = { ...current };
 84	        });
 85	      },
 86	      { injector: this.injector },
 87	    );
 88	  }
 89	
 90	  /** The two narrowing accessors of ADR-0004: the only casts, selected by the field type. */
 91	  protected text(key: string): FieldTree<string> {
 92	    return this.form[key] as unknown as FieldTree<string>;
 93	  }
 94	  protected flag(key: string): FieldTree<boolean> {
 95	    return this.form[key] as unknown as FieldTree<boolean>;
 96	  }
 97	
 98	  /**
 99	   * Runs before the browser applies a keystroke to a number input. Signal Forms writes the model
100	   * back into the DOM from a deferred flush; if that flush is still pending when the next key
101	   * makes the text unparseable (`1` then `e`), it would overwrite the text being typed with the
102	   * stale model value. Flushing now makes it a no-op (the DOM already holds that value), so the
103	   * typed text stays visible. The model is never touched here.
104	   */
105	  protected flushBindings(): void {
106	    this.appRef.tick();
107	  }
108	
109	  /**
110	   * The message to show (spec AC-09): input the browser cannot parse keeps the last parseable text
111	   * in the model and Signal Forms reports a parse error without a message, so that case is
112	   * evaluated as an empty value: `requiredMessage ?? errorMessage`. The field stays invalid while
113	   * the unparseable text is on screen, so "Continuar" never accepts it.
114	   */
115	  protected errorOf(config: FieldConfig): string | null {
116	    const state = this.form[config.key]();
117	    if (!state.touched() || !state.invalid()) return null;
118	    const errors = state.errors();
119	    if (errors.some((error) => error.kind === 'parse')) {
120	      return validateField(config, '', this.clock()) ?? config.errorMessage;
121	    }
122	    return errors[0]?.message ?? null;
123	  }
124	
125	  protected describedBy(config: FieldConfig, error: string | null): string | null {
126	    const ids = [
127	      config.helpText ? `${config.key}-help` : '',
128	      error ? `${config.key}-error` : '',
129	    ].filter(Boolean);
130	    return ids.length > 0 ? ids.join(' ') : null;
131	  }
