 17	import { validateField } from '../../shared/field-validators';
 18	import { hydrate } from '../../shared/field-values';
 19	
 20	/**
 21	 * The step 1 form (ADR-0004): Signal Forms over the shared validation core. The editing model is
 22	 * `Record<string, string | boolean>` (never null); each field has exactly one `validate()` that
 23	 * calls the pure `validateField`. Built once per instance, hydrated from the wizard state; a
 24	 * different configuration means a new instance (the page recreates it).
 25	 */
 26	@Component({
 27	  selector: 'app-quote-form',
 28	  imports: [FormField, FormRoot],
 29	  templateUrl: './quote-form.html',
 30	  styleUrl: './quote-form.css',
 31	})
 32	export class QuoteForm implements OnInit {
 33	  readonly configs = input.required<FieldConfig[]>();
 34	  readonly countryCode = input.required<string>();
 35	
 36	  private readonly appRef = inject(ApplicationRef);
 37	  private readonly injector = inject(Injector);
 38	  private readonly clock = inject(CLOCK);
 39	  private readonly quote = inject(QuoteStore);
 40	  private readonly router = inject(Router);
 41	
 42	  protected form!: FieldTree<RawValues>;
 43	
 44	  ngOnInit(): void {
 45	    const configs = this.configs();
 46	    const model = signal<RawValues>(hydrate(configs, this.quote.values()));
 47	    this.form = form(
 48	      model,
 49	      (root) => {
 50	        for (const config of configs) {
 51	          validate(root[config.key], ({ value }) => {
 52	            const message = validateField(config, value(), this.clock());
 53	            return message ? { kind: 'custom', message } : undefined;
 54	          });
 55	        }
 56	      },
 57	      {
 58	        injector: this.injector,
 59	        submission: {
 60	          action: async () => {
 61	            if (this.quote.completeStep1(configs) !== null) {
 62	              await this.router.navigate(['/', this.countryCode().toLowerCase(), 'planes']);
 63	            }
 64	            return undefined;
 65	          },
 66	          onInvalid: (root) => {
 67	            const first = configs.find((config) => root[config.key]().invalid());
 68	            if (first) root[first.key]().focusBoundControl();
 69	          },
 70	        },
 71	      },
 72	    );
 73	
 74	    // The raw editing values are written to the wizard state on every change (ADR-0003).
 75	    let synced: RawValues = { ...model() };
 76	    effect(
 77	      () => {
 78	        const current = model();
 79	        untracked(() => {
 80	          for (const [key, value] of Object.entries(current)) {
 81	            if (synced[key] !== value) this.quote.setValue(key, value);
 82	          }
 83	          synced = { ...current };
 84	        });
 85	      },
 86	      { injector: this.injector },
 87	    );
 88	  }
