 90	  /** The two narrowing accessors of ADR-0004: the only casts, selected by the field type. */
 91	  protected text(key: string): FieldTree<string> {
 92	    return this.form[key] as unknown as FieldTree<string>;
 93	  }
 94	  protected flag(key: string): FieldTree<boolean> {
 95	    return this.form[key] as unknown as FieldTree<boolean>;
 96	  }
 97	
 98	  /**
 99	   * Runs before the browser applies a keystroke to a number input. Signal Forms writes the model
100	   * back into the DOM from a deferred flush; if that flush is still pending when the next key
101	   * makes the text unparseable (`1` then `e`), it would overwrite the text being typed with the
102	   * stale model value. Flushing now makes it a no-op (the DOM already holds that value), so the
103	   * typed text stays visible. The model is never touched here.
104	   */
105	  protected flushBindings(): void {
106	    this.appRef.tick();
107	  }
108	
109	  /**
110	   * The message to show (spec AC-09): input the browser cannot parse keeps the last parseable text
111	   * in the model and Signal Forms reports a parse error without a message, so that case is
112	   * evaluated as an empty value: `requiredMessage ?? errorMessage`. The field stays invalid while
113	   * the unparseable text is on screen, so "Continuar" never accepts it.
114	   */
115	  protected errorOf(config: FieldConfig): string | null {
116	    const state = this.form[config.key]();
117	    if (!state.touched() || !state.invalid()) return null;
118	    const errors = state.errors();
119	    if (errors.some((error) => error.kind === 'parse')) {
120	      return validateField(config, '', this.clock()) ?? config.errorMessage;
121	    }
122	    return errors[0]?.message ?? null;
123	  }
124	
125	  protected describedBy(config: FieldConfig, error: string | null): string | null {
126	    const ids = [
127	      config.helpText ? `${config.key}-help` : '',
128	      error ? `${config.key}-error` : '',
129	    ].filter(Boolean);
130	    return ids.length > 0 ? ids.join(' ') : null;
131	  }
