 15	test.describe('US-01-AC-27 read-only content access, data stays in the browser', () => {
 16	  test('US-01-AC-27 from the first page load to step 2 every content request is a GET, none carries a token, none contains what I typed', async ({ page }) => {
 17	    const requests: Request[] = [];
 18	    page.on('request', (request) => requests.push(request));
 19	
 20	    await page.goto('/co/datos');
 21	    await expect(field(page, 'Placa')).toBeVisible();
 22	    await fillColombia(page);
 23	    await continuar(page).click();
 24	    await expect(page).toHaveURL(/\/co\/planes$/);
 25	
 26	    const apiRequests = requests.filter((r) => new URL(r.url()).pathname.startsWith('/api/'));
 27	    expect(apiRequests.length, 'the flow must have read content through /api').toBeGreaterThan(0);
 28	
 29	    // Every request to the content backend is a read.
 30	    expect(apiRequests.map((r) => r.method()).filter((m) => m !== 'GET')).toEqual([]);
 31	
 32	    // The browser only talks to the front end origin: Strapi's own port is never contacted.
 33	    const strapiOrigin = new URL(STRAPI_URL).origin;
 34	    const frontendOrigin = new URL(BASE_URL).origin;
 35	    expect(requests.map((r) => new URL(r.url()).origin).filter((o) => o === strapiOrigin && o !== frontendOrigin)).toEqual([]);
 36	
 37	    // No request of the whole flow carries credentials.
 38	    const carrying: string[] = [];
 39	    for (const request of requests) {
 40	      const headers = await request.allHeaders();
 41	      if ('authorization' in headers) carrying.push(`${request.method()} ${new URL(request.url()).pathname}`);
 42	    }
 43	    expect(carrying).toEqual([]);
 44	
 45	    // No request, to any address, contains a value entered in step 1 (URL, query or body).
 46	    const entered = ['Ana Prueba Ficticia', '1012345678', 'ABC123', '3 Touring', '1990-05-15', 'Medellín'];
 47	    const leaks: string[] = [];
 48	    for (const request of requests) {
 49	      const haystack = [request.url(), decodeURIComponent(request.url()), request.postData() ?? ''].join('\n').toLowerCase();
 50	      for (const value of entered) {
 51	        if (haystack.includes(value.toLowerCase()) || haystack.includes(encodeURIComponent(value).toLowerCase())) {
 52	          leaks.push(`${request.method()} ${new URL(request.url()).pathname} contains a typed value`);
 53	        }
 54	      }
 55	    }
 56	    expect(leaks).toEqual([]);
 57	  });
 58	});
