 62	    status: 'draft',
 63	    'filters[key][$eq]': 'email',
 64	    'filters[country][code][$eq]': 'CO',
 65	  };
 66	  const PUBLISHED_QUERY = { 'filters[country][code][$eq]': 'CO' };
 67	  const EXTRA_PUBLICATION_PARAMS: Record<string, string>[] = [
 68	    { publicationFilter: 'never-published' },
 69	    { hasPublishedVersion: 'false' },
 70	    { publicationState: 'preview' },
 71	  ];
 72	
 73	  async function bodyKeys(response: Awaited<ReturnType<APIRequestContext['get']>>): Promise<string[]> {
 74	    if (!response.ok()) return [];
 75	    const body = (await response.json()) as { data?: { key?: string }[] };
 76	    return (body.data ?? []).map((item) => item.key ?? '');
 77	  }
