 79	  async function expectNoDraftEmail(response: Awaited<ReturnType<APIRequestContext['get']>>): Promise<void> {
 80	    // Whatever the status (an empty list, or a refusal), the draft must not be in the response.
 81	    expect(response.status(), 'the request must not crash the server').toBeLessThan(500);
 82	    expect(await bodyKeys(response)).not.toContain('email');
 83	    expect(await response.text()).not.toContain('Correo electrónico');
