111	      for (const extra of EXTRA_PUBLICATION_PARAMS) {
112	        await expectNoDraftEmail(await strapi.get('/api/form-fields', { params: { ...DRAFT_QUERY, ...extra } }));
113	        await expectNoDraftEmail(await request.get('/api/form-fields', { params: { ...DRAFT_QUERY, ...extra } }));
114	      }
