139	  test('US-01-AC-28 the proxy answers other write methods with 405 and rejects an Authorization header', async ({ request }) => {
140	    for (const method of ['put', 'delete', 'patch'] as const) {
141	      const response = await request[method]('/api/form-fields/anyDocumentId', { data: { data: { label: 'x' } } });
142	      expect([404, 405]).toContain(response.status());
143	    }
144	    const withToken = await request.get('/api/form-fields', {
145	      params: PUBLISHED_QUERY,
146	      headers: { Authorization: 'Bearer not-a-real-token-for-a-negative-test' }, // scan-secrets: allow (fictitious value, negative test for ADR-0002)
147	    });
148	    expect(withToken.status()).toBe(400);
149	  });
