151	  // F02 of review R1: the published-only rule must not depend on how the caller spells the request.
152	  // Fictitious header values: none of them is a credential.
153	  const NON_BEARER_HEADERS: Record<string, string>[] = [
154	    { Authorization: 'foo' }, // scan-secrets: allow (fictitious value, negative test for ADR-0002)
155	    { Authorization: 'Basic Zm9vOmJhcg==' }, // scan-secrets: allow (fictitious value "foo:bar", negative test for ADR-0002)
156	    { Authorization: 'Bearer' }, // scan-secrets: allow (scheme without a token, negative test for ADR-0002)
157	    { authorization: 'x' }, // scan-secrets: allow (fictitious value, negative test for ADR-0002)
158	  ];
159	  const PATH_PREFIXES = ['/api', '/API', '/Api'];
160	
161	  type ApiResponse = Awaited<ReturnType<APIRequestContext['get']>>;
162	
163	  async function items(response: ApiResponse): Promise<{ key?: string; publishedAt?: string | null }[]> {
164	    // The proxy answers an unknown (upper-case) path with the SPA's HTML page: no rows, no draft.
